    "fonte": "Moore e Persaud, Embriologia Clínica (Elsevier); Madeira, Anatomia da Face (Sarvier). Imagens: Anthony Graham, CC BY 4.0; Henry Vandyke Carter (Gray's Anatomy), domínio público (Wikimedia Commons)",
