    "d": "Formação do dente, em fases: botão, capuz e campânula, seguidas pela formação da coroa e da raiz.",
    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Katchburian e Arana, Histologia e Embriologia Oral (Guanabara Koogan). Imagens: Thesleff e Tummers (StemBook), CC BY 3.0; Dozenist, CC BY-SA 3.0 (Wikimedia Commons)",
