    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Katchburian e Arana, Histologia e Embriologia Oral (Guanabara Koogan). Imagens: Pinkmanggis, CC BY-SA 4.0 (Wikimedia Commons)",
