   "nervo trigêmeo": {
    "d": "Quinto nervo craniano (V), principal nervo sensitivo da face e da boca. Tem três divisões: oftálmico (V1), maxilar (V2) e mandibular (V3); só o V3 leva a raiz motora. Ex.: quase toda a anestesia odontológica é anestesia de ramos do trigêmeo: os dentes de cima pelo V2 e os de baixo pelo V3.",
    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Madeira, Anatomia da Face (Sarvier). Imagens: John C. B. Grant (1962), domínio público; Henry Vandyke Carter (Gray's Anatomy), domínio público (Wikimedia Commons)",
    "img": [
     "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Grant_1962_654.png/960px-Grant_1962_654.png",
     "https://upload.wikimedia.org/wikipedia/commons/2/20/Gray784.png",
     "https://upload.wikimedia.org/wikipedia/commons/8/83/Gray778.png"
    ],
    "legs": [
     "Esquema das três divisões do trigêmeo (Grant, em inglês).",
     "Áreas sensitivas da cabeça (Gray): V1, V2, V3 e o plexo cervical no ângulo da mandíbula.",
     "Nervos maxilar e mandibular (Gray): alveolares superiores, infraorbital, alveolar inferior, lingual e mentual."
    ],
    "alts": [
     "Esquema do nervo trigêmeo",
     "Desenho da cabeça com as áreas sensitivas coloridas",
     "Desenho dos ramos do nervo maxilar e mandibular"
    ]
   },
