    "d": "Pode ser o nervo facial (VII), que move os músculos da mímica, ou a artéria facial, ramo da carótida externa que sobe pelo rosto e termina como angular. O contexto diz qual dos dois.",
    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Madeira, Anatomia da Face (Sarvier). Imagens: Patrick J. Lynch, CC BY 2.5; Henry Vandyke Carter (Gray's Anatomy), domínio público (Wikimedia Commons)",
