    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Madeira, Anatomia da Face (Sarvier). Imagens: Gray's Anatomy, modificado por Uwe Gille, domínio público; Henry Vandyke Carter (Gray's Anatomy), domínio público (Wikimedia Commons)",
