    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Madeira, Anatomia da Face (Sarvier). Imagens: Henry Vandyke Carter (Gray's Anatomy), destaque de Helgo13, domínio público (Wikimedia Commons)",
