    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Madeira, Anatomia da Face (Sarvier). Imagens: Henry Vandyke Carter (Gray's Anatomy), domínio público; BruceBlaus (Blausen.com), CC BY 3.0 (Wikimedia Commons)",
