   "linfonodo": {
    "d": "Pequeno órgão em forma de feijão que filtra a linfa. Inflamado: móvel, mole e doloroso. Suspeito de câncer: duro, fixo e indolor. Ex.: num abscesso dentário, o linfonodo submandibular fica doloroso e móvel e diminui depois do tratamento do dente; um linfonodo duro, fixo e indolor que não some precisa ser investigado.",
    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Neville et al., Patologia Oral e Maxilofacial (Elsevier). Imagens: KC Panchal, domínio público; Mikael Häggström, CC0 (Wikimedia Commons)",
    "img": [
     "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Schematic_of_lymph_node_showing_lymph_sinuses.svg/960px-Schematic_of_lymph_node_showing_lymph_sinuses.svg.png",
     "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Cervical_lymph_nodes_and_levels.png/960px-Cervical_lymph_nodes_and_levels.png"
    ],
    "legs": [
     "Esquema de um linfonodo (em inglês).",
     "Linfonodos da cabeça e do pescoço, com o submentual e o submandibular (em inglês)."
    ],
    "alts": [
     "Esquema de linfonodo",
     "Esquema dos linfonodos do pescoço"
    ]
   },
