   "músculo estriado esquelético": {
    "d": "Tecido muscular voluntário: fibras longas, cilíndricas e multinucleadas, com núcleos na periferia e estrias transversais (sarcômeros). Ex.: na lâmina em HE, para diferenciar do músculo liso, olhe os núcleos: no esquelético ficam vários na borda da fibra; no liso, um só no meio da célula.",
    "fonte": "Resumo e questões de Bases Morfofuncionais da turma; Junqueira e Carneiro, Histologia Básica (Guanabara Koogan). Imagens: RWhitwam, CC BY-SA 4.0; Rollroboter, CC BY-SA 3.0 (Wikimedia Commons)",
    "img": [
     "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Skeletal-muscle_058_thin_section.png/960px-Skeletal-muscle_058_thin_section.png",
     "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Muskel_%28_1%29.jpg/960px-Muskel_%28_1%29.jpg"
    ],
    "legs": [
     "Músculo estriado esquelético em HE: fibras rosas com estrias e núcleos na periferia.",
     "Músculo esquelético em corte longitudinal: estrias transversais e muitos núcleos por fibra."
    ],
    "alts": [
     "Lâmina de músculo esquelético corada em rosa",
     "Lâmina de músculo esquelético em corte longitudinal"
    ]
   },
